import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { apiFetch } from "./core.js";

/**
 * `apiFetch`'s body/header contract — and specifically F-A (CI-21), the
 * pre-existing defect this cycle is the first to reach.
 *
 * The default `content-type: application/json` was guarded by "a body exists",
 * not by "the body is JSON". A `FormData` body therefore left this wrapper
 * labelled `application/json` **with no multipart boundary**, which no server
 * can parse: the boundary is generated by the fetch implementation while it
 * serialises the parts, and the Fetch standard only lets it fill the header in
 * when the request carries none. The CSV import wizard is this codebase's
 * first `FormData` caller, so the bug had never had an opportunity to fire —
 * it is real, not hypothetical.
 *
 * ## Why this suite builds a real `Request`
 *
 * Asserting only "the wrapper did not set a header" would pass just as well if
 * the fix had disabled the header for *every* body type, and it would say
 * nothing about what actually arrives at the server. So each case takes the
 * exact `(url, init)` pair the wrapper handed to `fetch` and constructs the
 * `Request` the platform would have sent from it — then reads the header off
 * **that**, and reads the serialised body back to check the boundary it
 * announces is the boundary it actually delimits the parts with. The JSON case
 * is asserted the same way, with an exact equality, so a fix that suppressed
 * the header everywhere fails here rather than passing quietly.
 *
 * `document` is stubbed rather than this file being a `.test.tsx`: the DOM
 * surface under test is one cookie read, while `FormData`/`Headers`/`Request`
 * must all come from the *same* implementation for `instanceof` to mean
 * anything — jsdom supplies its own `FormData` but no `Request` at all, which
 * would mix two of them.
 */

const ORIGIN = "https://kerdial.test";

interface CapturedCall {
  readonly url: string;
  readonly init: RequestInit;
}

function capturedRequest(call: CapturedCall): Request {
  return new Request(new URL(call.url, ORIGIN), call.init);
}

describe("apiFetch — body/header contract (F-A)", () => {
  let fetchMock: ReturnType<typeof vi.fn>;

  function lastCall(): CapturedCall {
    const call = fetchMock.mock.calls.at(-1);
    expect(call).toBeDefined();
    return { url: String(call![0]), init: call![1] as RequestInit };
  }

  beforeEach(() => {
    fetchMock = vi.fn(
      () =>
        new Response(JSON.stringify({ ok: true }), {
          status: 200,
          headers: { "content-type": "application/json" },
        }),
    );
    vi.stubGlobal("fetch", fetchMock);
    vi.stubGlobal("document", { cookie: "csrf_token=csrf-abc-123" });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
  });

  function importUpload(): FormData {
    const body = new FormData();
    body.set("mode", "DRY_RUN");
    body.set("file", new Blob(["Date;Type\r\n"], { type: "text/csv" }), "assets.csv");
    return body;
  }

  it("sets no content-type of its own on a FormData body", async () => {
    await apiFetch("/imports/instruments", { method: "POST", body: importUpload() });

    expect(new Headers(lastCall().init.headers).has("content-type")).toBe(false);
  });

  it("the request that arrives carries multipart/form-data with a non-empty boundary, and that boundary really delimits the parts", async () => {
    await apiFetch("/imports/instruments", { method: "POST", body: importUpload() });

    // Built from the exact `(url, init)` pair the wrapper handed to `fetch`,
    // so this is what the platform sends, not what the client intended.
    const request = capturedRequest(lastCall());
    const contentType = request.headers.get("content-type");
    expect(contentType).not.toBeNull();
    const [mediaType, boundaryParam] = contentType!.split(";").map((part) => part.trim());
    expect(mediaType).toBe("multipart/form-data");
    const boundary = /^boundary=(.+)$/.exec(boundaryParam ?? "")?.[1];
    expect(boundary).toBeDefined();
    expect(boundary!.length).toBeGreaterThan(0);

    // The announced boundary is the one the parts are actually delimited by —
    // the property a server needs and the old code destroyed.
    const serialised = await request.text();
    expect(serialised).toContain(`--${boundary!}`);
    expect(serialised).toContain(`name="mode"`);
    expect(serialised).toContain(`filename="assets.csv"`);
  });

  it("still sends exactly application/json on a plain JSON body — the fix is not a blanket removal", async () => {
    await apiFetch("/transactions", { method: "POST", body: JSON.stringify({ kind: "BUY" }) });

    const call = lastCall();
    expect(new Headers(call.init.headers).get("content-type")).toBe("application/json");
    expect(capturedRequest(call).headers.get("content-type")).toBe("application/json");
  });

  it("echoes x-csrf-token and includes credentials on both body kinds", async () => {
    const form = new FormData();
    form.set("mode", "APPLY");

    await apiFetch("/imports/transactions", { method: "POST", body: form });
    const multipartCall = lastCall();
    expect(new Headers(multipartCall.init.headers).get("x-csrf-token")).toBe("csrf-abc-123");
    expect(multipartCall.init.credentials).toBe("include");

    await apiFetch("/transactions", { method: "POST", body: JSON.stringify({}) });
    const jsonCall = lastCall();
    expect(new Headers(jsonCall.init.headers).get("x-csrf-token")).toBe("csrf-abc-123");
    expect(jsonCall.init.credentials).toBe("include");
  });

  it("leaves an explicitly supplied content-type alone, and sets none at all on a bodiless GET", async () => {
    await apiFetch("/transactions/1", {
      method: "PATCH",
      body: JSON.stringify({}),
      headers: { "content-type": "application/merge-patch+json" },
    });
    expect(new Headers(lastCall().init.headers).get("content-type")).toBe(
      "application/merge-patch+json",
    );

    await apiFetch("/portfolios");
    const getCall = lastCall();
    expect(new Headers(getCall.init.headers).has("content-type")).toBe(false);
    expect(new Headers(getCall.init.headers).has("x-csrf-token")).toBe(false);
  });
});
